<div class="page-title">Accounts</div><p class="page-subtitle">Manage trading accounts, currencies and starting balances.</p><div class="card form-card"><div class="section-heading"><div><h2>Add account</h2><div class="sub">Create an account once, then reuse it when recording trades.</div></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="grid"><p><label>Name</label><input name="name" placeholder="Interactive Brokers" required></p><p><label>Currency</label><input name="currency" value="USD" maxlength="3" required></p><p><label>Initial balance</label><input name="initial_balance" type="number" step=".01" min="0" value="0" required></p></div><div class="actions"><button>Add account</button></div></form></div><?php foreach($accounts as $a):?><div class="card form-card"><div class="section-heading"><div><h2><?=e($a['name'])?></h2><div class="sub">Account configuration</div></div><span class="badge"><?=e($a['currency'])?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=e($a['id'])?>"><div class="grid"><p><label>Name</label><input name="name" value="<?=e($a['name'])?>" required></p><p><label>Currency</label><input name="currency" value="<?=e($a['currency'])?>" maxlength="3" required></p><p><label>Initial balance</label><input name="initial_balance" type="number" step=".01" min="0" value="<?=e($a['initial_balance'])?>" required></p></div><div class="actions"><button>Save changes</button></form><form method="post" onsubmit="return confirm('Delete account and its trades?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($a['id'])?>"><button class="danger">Delete</button></form></div></div><?php endforeach;?>